<template><div class="admin-frame" aria-hidden="true"><i v-for="corner in ['top-left','top-right','bottom-left','bottom-right']" :key="corner" class="admin-frame__corner" :class="`admin-frame__corner--${corner}`"/><i class="admin-frame__baseboard"/></div></template>
<style scoped>.admin-frame{position:fixed;z-index:0;inset:0;pointer-events:none}.admin-frame__corner{position:absolute;width:96px;height:96px;background:url('@/assets/pixel/common/frame/frame-corner.png') center/contain no-repeat;image-rendering:pixelated}.admin-frame__corner--top-left{top:0;left:0}.admin-frame__corner--top-right{top:0;right:0;transform:scaleX(-1)}.admin-frame__corner--bottom-left{bottom:0;left:0;transform:scaleY(-1)}.admin-frame__corner--bottom-right{right:0;bottom:0;transform:scale(-1)}.admin-frame__baseboard{position:absolute;right:0;bottom:0;left:0;height:32px;background:url('@/assets/pixel/common/frame/frame-baseboard.png') center bottom/auto 32px repeat-x;image-rendering:pixelated}@media(max-width:767px){.admin-frame__corner,.admin-frame__baseboard{display:none}}</style>
